نقش سازمانی: مدیر منابع انسانی (hr_manager)

درخواست کاربر:
نرخ ترک «واحد فنی و مهندسی» این سه‌ماهه از 7.6٪ به 13.9٪ رسیده و پروژه‌ها در خطرند. ریشهٔ واقعی کجاست؟ (مدیر منابع انسانی — هلدینگ خدماتی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "exits",
      "description": "خروجی‌ها: واحد، سابقه، دلیل و تاریخ",
      "dimensions": [
        "unit",
        "tenure",
        "reason"
      ],
      "measures": [
        "count"
      ]
    },
    {
      "dataset": "payroll",
      "description": "دستمزد و مزایا به تفکیک واحد",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "cost_m_toman"
      ]
    },
    {
      "dataset": "headcount",
      "description": "تعداد نیرو به تفکیک واحد و ماه",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "headcount"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "turnover_rate",
      "description": "نرخ ترک‌خدمت",
      "formula": "خروجی‌های دوره / میانگین نیرو",
      "unit": "درصد",
      "dimensions": [
        "unit",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت خدماتی-صنعتی با ۴۰۰ تا ۹۰۰ نفر نیرو در پنج واحد",
    "دورهٔ گزارش ماهانه؛ داده‌های منابع انسانی تا پایان همان ماه در دسترس است",
    "سیاست پرداخت سالانه بازبینی می‌شود؛ بازار نیروی فنی رقابتی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "turnover_rate"
    ],
    "period": [
      "prev_quarter",
      "curr_quarter"
    ],
    "comparison": "quarter_over_quarter"
  }
}

TOOL_OBSERVATION:
{
  "turnover_pct": {
    "prev_quarter": 7.6,
    "curr_quarter": 13.9,
    "unit": "واحد فنی و مهندسی"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "exits",
    "filters": {
      "unit": "واحد فنی و مهندسی",
      "period": "curr_quarter"
    }
  }
}

TOOL_OBSERVATION:
{
  "exits_by_tenure": {
    "بالای ۵ سال سابقه (مهندسان ارشد)": 72,
    "کمتر از ۲ سال": 29
  },
  "dominant_reason": "پیشنهاد حقوق بالاتر از رقبا"
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "payroll",
    "filters": {
      "unit": "واحد فنی و مهندسی",
      "period": "curr_quarter"
    }
  }
}

TOOL_OBSERVATION:
{
  "market_gap_note": "بررسی حقوق بازار نشان می‌دهد حقوق مهندسان ارشد این واحد 20٪ زیر میانگین بازار است و دو رقیب در سه ماه اخیر جذب فعال داشته‌اند"
}

نقش سازمانی: مدیر منابع انسانی (hr_manager)

درخواست کاربر:
11 مهندس ارشد واحد فنی در خطر خروج‌اند (شکاف حقوقی 17٪ با بازار). بین افزایش حقوق و جایگزینی کدام به‌صرفه‌تر است؟ (مدیر منابع انسانی — شرکت لجستیک و حمل)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "hires",
      "description": "استخدام‌ها: تعداد، هزینه و منبع جذب",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "count",
        "cost_m_toman"
      ]
    },
    {
      "dataset": "payroll",
      "description": "دستمزد و مزایا به تفکیک واحد",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "cost_m_toman"
      ]
    },
    {
      "dataset": "vacancy_log",
      "description": "سوابق جای خالی: تاریخ باز و پر شدن",
      "dimensions": [
        "unit",
        "position"
      ],
      "measures": [
        "days_to_fill"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "cost_per_hire",
      "description": "هزینهٔ هر استخدام",
      "formula": "مجموع هزینهٔ جذب و آموزش / تعداد استخدام",
      "unit": "میلیون تومان",
      "dimensions": [
        "unit",
        "period"
      ]
    },
    {
      "metric": "time_to_fill",
      "description": "زمان پر کردن جای خالی",
      "formula": "میانگین روز از تأیید سمت تا حضور نیرو",
      "unit": "روز",
      "dimensions": [
        "unit",
        "position"
      ]
    }
  ],
  "business_context": [
    "شرکت خدماتی-صنعتی با ۴۰۰ تا ۹۰۰ نفر نیرو در پنج واحد",
    "دورهٔ گزارش ماهانه؛ داده‌های منابع انسانی تا پایان همان ماه در دسترس است"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "cost_per_hire"
    ],
    "period": "last_quarter",
    "comparison": null
  }
}

TOOL_OBSERVATION:
{
  "cost_per_hire_m_toman": 95,
  "note": "فقط جذب؛ بدون افت بهره‌وری شش‌ماههٔ نیروی جدید"
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "time_to_fill"
    ],
    "period": "curr_quarter",
    "comparison": null
  }
}

TOOL_OBSERVATION:
{
  "time_to_fill_days": 105,
  "position": "مهندس ارشد"
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "payroll",
    "filters": {
      "unit": "واحد فنی و مهندسی",
      "period": "curr_quarter"
    }
  }
}

TOOL_OBSERVATION:
{
  "raise_cost_annual_m_toman": 460,
  "replacement_full_cost_annual_m_toman": 810,
  "market_gap_pct": 17
}

