        "unit",
        "month"
      ],
      "measures": [
        "count",
        "cost_m_toman"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "cost_per_hire",
      "description": "هزینهٔ هر استخدام",
      "formula": "مجموع هزینهٔ جذب و آموزش / تعداد استخدام",
      "unit": "میلیون تومان",
      "dimensions": [
        "unit",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت خدماتی-صنعتی با ۴۰۰ تا ۹۰۰ نفر نیرو در پنج واحد",
    "دورهٔ گزارش ماهانه؛ داده‌های منابع انسانی تا پایان همان ماه در دسترس است"
  ]
