    },
    {
      "month": "m5",
      "value": 17
    },
    {
      "month": "m6",
      "value": 165
    }
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "hires",
    "filters": {
      "period": "m6"
    }
  }
}

TOOL_OBSERVATION:
{
  "m6": {
    "هزینهٔ کارمزد آژانس استخدام (پروژهٔ مهندسی)": 110,
    "تعداد استخدام": 24,
    "note": "استخدام انبوه یک‌باره برای پروژهٔ جدید؛ کارمزد آژانس به‌صورت مقطوع در همین ماه ثبت شده"
  }
}

