این سه‌ماهه هم ترک‌خدمت بالا رفته هم بهره‌وری هر نفر. مدیر تولید می‌گوید فشار بیشتر کارکنان باعث ترک‌خدمت شده و باید از اتوماسیون کم کنیم. درست است؟ (مدیر منابع انسانی — تولیدی مواد غذایی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "exits",
      "description": "خروجی‌ها: واحد، سابقه، دلیل و تاریخ",
      "dimensions": [
        "unit",
        "tenure",
        "reason"
      ],
      "measures": [
        "count"
      ]
    },
    {
      "dataset": "dept_output",
      "description": "خروجی واحدها (شاخص تولید)",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "output_index"
      ]
    },
    {
      "dataset": "headcount",
      "description": "تعداد نیرو به تفکیک واحد و ماه",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "headcount"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "turnover_rate",
      "description": "نرخ ترک‌خدمت",
      "formula": "خروجی‌های دوره / میانگین نیرو",
      "unit": "درصد",
      "dimensions": [
        "unit",
        "period"
      ]
    },
    {
      "metric": "productivity_per_head",
      "description": "بهره‌وری هر نفر",
      "formula": "خروجی واحد / نیروی فعال",
      "unit": "شاخص بر نفر",
      "dimensions": [
        "unit",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت خدماتی-صنعتی با ۴۰۰ تا ۹۰۰ نفر نیرو در پنج واحد",
    "دورهٔ گزارش ماهانه؛ داده‌های منابع انسانی تا پایان همان ماه در دسترس است"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "turnover_rate",
    "period_a": "prev_quarter",
    "period_b": "curr_quarter"
  }
}

TOOL_OBSERVATION:
{
  "turnover_pct": {
    "prev": 9.7,
    "curr": 16.0
  },
  "by_unit": {
    "واحد فروش": "رشد اصلی",
    "سایر": "ثابت"
  }
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "productivity_per_head",
    "period_a": "prev_quarter",
    "period_b": "curr_quarter"
  }
}

TOOL_OBSERVATION:
{
  "productivity_index_per_head": {
    "prev": 11.1,
    "curr": 14.899999999999999
  },
  "driver": "اتوماسیون فرایند سفارش و کاهش نیروی غیرمستقیم در واحد پشتیبانی"
}

